public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Step 1: Create a graph from the edge list
    Graph graph = new Graph(n, edges);

    // Step 2: Perform BFS to find the shortest path from node 0 to all other nodes
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    int[] distance = new int[n];
    Arrays.fill(distance, -1);
    queue.add(0);
    visited[0] = true;
    distance[0] = 0;

    while (!queue.isEmpty()) {
        int node = queue.remove();
        for (int neighbor : graph.getNeighbors(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[node] + 1;
                queue.add(neighbor);
            }
        }
    }

    // Step 3: Find the shortest path to all nodes that have an apple
    int time = 0;
    for (int node = 0; node < n; node++) {
        if (hasApple[node]) {
            if (distance[node] == -1) {
                return -1;
            }
            time = Math.max(time, distance[node]);
        }
    }

    return time;
